use std::io::{self, BufRead};

struct P {
    t: Vec<String>,
    i: usize,
    out: Vec<String>,
}

impl P {
    fn peek(&self) -> Option<&str> {
        self.t.get(self.i).map(|s| s.as_str())
    }
    fn expr(&mut self) -> Option<()> {
        self.term()?;
        while let Some(op) = self.peek() {
            if op == "+" || op == "-" {
                let op = op.to_string();
                self.i += 1;
                self.term()?;
                self.out.push(op);
            } else {
                break;
            }
        }
        Some(())
    }
    fn term(&mut self) -> Option<()> {
        self.pow()?;
        while let Some(op) = self.peek() {
            if op == "*" || op == "/" {
                let op = op.to_string();
                self.i += 1;
                self.pow()?;
                self.out.push(op);
            } else {
                break;
            }
        }
        Some(())
    }
    fn pow(&mut self) -> Option<()> {
        self.atom()?;
        if self.peek() == Some("^") {
            self.i += 1;
            self.pow()?;
            self.out.push("^".to_string());
        }
        Some(())
    }
    fn atom(&mut self) -> Option<()> {
        let t = self.peek()?.to_string();
        if t == "(" {
            self.i += 1;
            self.expr()?;
            if self.peek() != Some(")") {
                return None;
            }
            self.i += 1;
            Some(())
        } else if t.chars().all(|c| c.is_ascii_digit()) {
            self.i += 1;
            self.out.push(t);
            Some(())
        } else {
            None
        }
    }
}

fn convert(line: &str) -> Option<String> {
    let mut t = Vec::new();
    let c: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < c.len() {
        let ch = c[i];
        if ch.is_whitespace() {
            i += 1;
        } else if ch.is_ascii_digit() {
            let s = i;
            while i < c.len() && c[i].is_ascii_digit() {
                i += 1;
            }
            t.push(c[s..i].iter().collect());
        } else if "+-*/^()".contains(ch) {
            t.push(ch.to_string());
            i += 1;
        } else {
            return None;
        }
    }
    let mut p = P { t, i: 0, out: vec![] };
    p.expr()?;
    if p.i != p.t.len() {
        return None;
    }
    Some(p.out.join(" "))
}

fn main() {
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
            continue;
        }
        match convert(&line) {
            Some(s) => println!("{}", s),
            None => println!("error"),
        }
    }
}

